import { useState, type FormEvent } from 'react';
import { Badge, Button, Card, Input, Stack, Text } from '@jinx-ui/react';

export type RegistrationValues = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_VALUES: RegistrationValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);

  const isLastStep = step === STEPS.length - 1;

  const setField = (field: keyof RegistrationValues) => (event: { target: { value: string } }) => {
    setValues((previous) => ({ ...previous, [field]: event.target.value }));
  };

  const goBack = () => setStep((current) => Math.max(0, current - 1));

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(STEPS.length - 1, current + 1));
  };

  return (
    <Card>
      <form onSubmit={handleSubmit}>
        <Stack direction="column" gap="var(--jx-space-lg)">
          <Stack
            direction="row"
            gap="var(--jx-space-sm)"
            aria-label="Прогресс регистрации"
          >
            {STEPS.map((label, index) => (
              <Stack
                key={label}
                direction="row"
                gap="var(--jx-space-xs)"
                aria-current={index === step ? 'step' : undefined}
              >
                <Badge tone={index <= step ? 'accent' : 'neutral'}>{index + 1}</Badge>
                <Text
                  style={{
                    color:
                      index === step
                        ? 'var(--jx-color-text-primary)'
                        : 'var(--jx-color-text-muted)',
                  }}
                >
                  {label}
                </Text>
              </Stack>
            ))}
          </Stack>

          {step === 0 && (
            <Stack direction="column" gap="var(--jx-space-md)">
              <Input
                label="Имя и фамилия"
                name="fullName"
                value={values.fullName}
                onChange={setField('fullName')}
                required
              />
              <Input
                label="Электронная почта"
                name="email"
                type="email"
                value={values.email}
                onChange={setField('email')}
                required
              />
              <Input
                label="Телефон"
                name="phone"
                type="tel"
                value={values.phone}
                onChange={setField('phone')}
              />
            </Stack>
          )}

          {step === 1 && (
            <Stack direction="column" gap="var(--jx-space-md)">
              <Input
                label="Страна"
                name="country"
                value={values.country}
                onChange={setField('country')}
                required
              />
              <Input
                label="Город"
                name="city"
                value={values.city}
                onChange={setField('city')}
                required
              />
              <Input
                label="Улица и дом"
                name="street"
                value={values.street}
                onChange={setField('street')}
                required
              />
              <Input
                label="Индекс"
                name="zip"
                value={values.zip}
                onChange={setField('zip')}
              />
            </Stack>
          )}

          {step === 2 && (
            <Stack direction="column" gap="var(--jx-space-sm)">
              <Text>Имя и фамилия: {values.fullName}</Text>
              <Text>Электронная почта: {values.email}</Text>
              <Text>Телефон: {values.phone}</Text>
              <Text>Страна: {values.country}</Text>
              <Text>Город: {values.city}</Text>
              <Text>Улица и дом: {values.street}</Text>
              <Text>Индекс: {values.zip}</Text>
            </Stack>
          )}

          <Stack direction="row" gap="var(--jx-space-sm)">
            <Button type="button" variant="secondary" onClick={goBack} disabled={step === 0}>
              Назад
            </Button>
            <Button type="submit" variant="primary">
              {isLastStep ? 'Отправить' : 'Дальше'}
            </Button>
          </Stack>
        </Stack>
      </form>
    </Card>
  );
}

export default RegistrationWizard;

